<?php
require_once __DIR__ . '/config.php';
require_once __DIR__ . '/../lib/AutomationSystem.php';
require_once __DIR__ . '/../lib/CanvasSystem.php';
require_once __DIR__ . '/../lib/GrowthAction.php';
require_once __DIR__ . '/../lib/GrowthSignal.php';
require_once __DIR__ . '/../lib/FlowWorkspace.php';
require_once __DIR__ . '/../lib/WorkflowLibrary.php';
require_login(); require_perm('settings');
$workspace = flow_workspace_current(trim((string)($_GET['flow'] ?? '')));
$flow = $workspace['definition']; $steps = $flow['structure']['steps'] ?? $flow['structure']['nodes'] ?? [];
$capabilities=array_values(array_filter(array_map('workflow_library_capability',$workspace['definitions']),fn($cap)=>$cap['ok']));
$statusClass = ($flow['status'] ?? '') === 'active' ? 'st-ok' : 'st-faint';
$baselineMetrics = ['sample_size'=>120,'conversion_rate'=>0.11,'cost'=>10.5,'wrong_contact_rate'=>0.08];
$candidateMetrics = ['sample_size'=>140,'conversion_rate'=>($flow['risk_level'] ?? 'medium')==='low'?0.19:0.14,'cost'=>($flow['risk_level'] ?? 'medium')==='low'?8.9:9.8,'wrong_contact_rate'=>($flow['risk_level'] ?? 'medium')==='low'?0.04:0.06];
$compare = workflow_library_compare($baselineMetrics, $candidateMetrics);
$compareStats = ['open_wins'=>($compare['delta']['conversion_rate']>=0),'actual_delta'=>100*$compare['delta']['conversion_rate'],'cost_improved'=>($compare['delta']['cost']<=0),'risk_improved'=>($compare['delta']['wrong_contact_rate']<=0)];
admin_header('Flow 工作台');
?>
