  <div class="panel" style="margin-bottom:16px"><div class="p-body" style="display:flex;gap:12px;align-items:end;flex-wrap:wrap"><form method="get" style="display:flex;gap:10px;align-items:end;flex-wrap:wrap"><label style="min-width:280px;flex:1"><span class="text-xs text-muted">选择现有 Flow</span><select name="flow" onchange="this.form.submit()" style="width:100%;margin-top:5px"><?php foreach($workspace['definitions'] as $item): ?><option value="<?=htmlspecialchars($item['id'])?>" <?=$item['id']===$workspace['selected_id']?'selected':''?>><?=htmlspecialchars($item['name'] ?: $item['id'])?> · <?=htmlspecialchars($item['source_type'])?></option><?php endforeach; ?></select></label><noscript><button class="btn btn-primary btn-sm">查看</button></noscript></form><span class="text-xs text-muted">共 <?=$workspace['counts']['definitions']?> 条 Flow；此页没有保存、启停或执行按钮。</span></div></div>
